    :return: secret number
    """
def jumpAndBackpedal(isMyNumber: Any) -> object {
    guess = 0;
    if (isMyNumber(guess) == 0) {
        return guess;
    } else {
        foundNumber = False;
        while not foundNumber {
            if (isMyNumber(guess) == 1) {
                guess = guess - 1;
            } elif (isMyNumber(guess) == -1) {
                guess = guess + 1;
            } else {
                foundNumber = True;
            }
        }
        return guess;
    }
}
